import sys
import heapq

def find(x):
    while x != parent[x]:
        parent[x] = parent[parent[x]]
        x = parent[x]
    return x

def union(x, y):
    rootX = find(x)
    rootY = find(y)
    if rootX != rootY:
        if rank[rootX] > rank[rootY]:
            parent[rootY] = rootX
        elif rank[rootX] < rank[rootY]:
            parent[rootX] = rootY
        else:
            parent[rootY] = rootX
            rank[rootX] += 1

def kruskal_with_odd_degree(n, edges):
    result = []
    odd_edges = []
    for weight, u, v in edges:
        if len(odd_edges) % 2 == 0:
            odd_edges.append((weight, u, v))
            union(u, v)
        else:
            if find(u) != find(v):
                odd_edges.append((weight, u, v))
                union(u, v)
            else:
                min_heap = []
                for w, x, y in odd_edges:
                    if find(x) != find(y):
                        heapq.heappush(min_heap, (w, x, y))
                if min_heap:
                    w, x, y = heapq.heappop(min_heap)
                    union(x, y)
                    odd_edges.append((w, x, y))
                else:
                    result.append(-1)
                    continue
        degree = [0] * (n + 1)
        for _, x, y in odd_edges:
            degree[x] += 1
            degree[y] += 1
        if all(d % 2 == 1 for d in degree[1:]):
            result.append(max(w for w, _, _ in odd_edges))
        else:
            result.append(-1)
    return result

def main():
    import sys
    input = sys.stdin.read().split()
    index = 0
    n = int(input[index])
    m = int(input[index + 1])
    index += 2
    edges = []
    for _ in range(m):
        a = int(input[index])
        b = int(input[index + 1])
        l = int(input[index + 2])
        edges.append((l, a, b))
        index += 3
    edges.sort()
    global parent, rank
    parent = list(range(n + 1))
    rank = [0] * (n + 1)
    result = kruskal_with_odd_degree(n, edges)
    for r in result:
        print(r)

if __name__ == "__main__":
    main()
